/* OpenIC-assets-3.js - part 3 of 7 of the game icons for Open IC Creator's in-game window: icon sheets as data: URIs. OpenIC.iss loads the parts into the window's page
   (ISXOgreX.UI:EvalFile) one at a time once the window is open. Built by tools/build-window.js. The icons are
   EverQuest II's own art (Daybreak Game Company). */
(function () {
  var L = window.OpenIC_LIB;
  if (!L || !L.IC) return;
  var st = document.getElementById('openic-icon-sheets-3');
  if (!st) { st = document.createElement('style'); st.id = 'openic-icon-sheets-3'; (document.head || document.body).appendChild(st); }
  st.textContent = ".oic-sp-8{background-image:url(data:image/png;base64,);}\n.oic-sp-9{background-image:url(data:image/png;base64,);}\n.oic-sp-10{background-image:url(data:image/png;base64,);}\n.oic-sp-11{background-image:url(data:image/png;base64,);}\n.oic-sp-12{background-image:url(data:image/png;base64,);}\n.oic-sp-13{background-image:url(data:image/png;base64,);}\n.oic-sp-14{background-image:url(data:image/png;base64,);}\n.oic-sp-15{background-image:url(data:image/png;base64,);}\n";
  if (typeof window.ogreUISet === 'function') window.ogreUISet('openic', 'openic-assets-got', '3/7');
})();
